import {readFile, writeFile, copyFile} from 'node:fs/promises';
import {createHash} from 'node:crypto';
import assert from 'node:assert/strict';
const base='.runtime/board-card-independent-20261126/stage';
const out='tests/evidence/board-toolchain-card-20261126';
const sha=b=>createHash('sha256').update(b).digest('hex');
const candidate=JSON.parse(await readFile('.runtime/mindplus-board-selection-20261126/candidate.json'));
for(const f of candidate.files) assert.equal(sha(await readFile(f.path)),f.sha256,f.path);
for(const f of candidate.artifacts) assert.equal(sha(await readFile(f.path.replace('apps/web/dist',base))),f.sha256,f.path);
const evidence=JSON.parse(await readFile('apps/web/evidence/mindplus-parity-v07/upstream-byte-comparison.json'));
const gui=await readFile(`${base}/openblock-vendor/openblock-gui.js`,'utf8');
const marks=[...gui.matchAll(/^\/\* (\d+) \*\//gm)];
const modules=new Map(marks.map((m,i)=>[m[1],gui.slice(m.index,marks[i+1]?.index??gui.length)]));
for(const x of [...evidence.vm,...evidence.blockly]) assert.equal(sha(modules.get(x.id)),x.sha256,`protected ${x.id}`);
const logo=sha(await readFile(`${base}/branding/ccraft-logo.png`));
assert.equal(logo,'c927127553d58dcfdb4de6487da3a2c894266d6a78b9de05d3e9535da2d010c2');
const calls=JSON.parse(await readFile('.runtime/board-card-independent-20261126/calls.json'));
assert.equal(calls.filter(c=>c.method==='POST'&&c.path==='/toolchains/prepare').length,1);
assert.equal(calls.filter(c=>c.method==='POST'&&!c.path.startsWith('/toolchains/')).length,0);
await copyFile('.runtime/board-card-independent-20261126/calls.json',`${out}/mock-calls.json`);
const result={candidateSourceHashes:true,frozenAssets:true,vm:evidence.vm.length,blockly:evidence.blockly.length,logo,preparePosts:1,physicalOperations:0,browserObserved:{current:'Arduino Uno',target:'Aijite ESP32-S3',cardCount:20,percent:25,unknownTotal:{value:null,max:null,text:'下载中\n取消下载'},viewport:[1280,720]},browserRemaining:'IAB provider disappeared after saved screenshots; completion/manual selection/upload-modal visual scenes not executed'};
await writeFile(`${out}/independent-summary.json`,JSON.stringify(result,null,2));
console.log(JSON.stringify(result,null,2));
